create table if not exists public.hub_wallets(member_id uuid primary key references auth.users(id) on delete cascade, balance bigint not null default 500000 check(balance>=0));
create table if not exists public.hub_casino_log(id bigint generated always as identity primary key, member_id uuid not null references auth.users(id), actor uuid not null references auth.users(id), kind text not null, bet bigint not null default 0, payout bigint not null default 0, reels integer[], balance bigint not null, created_at timestamptz default now());
alter table public.hub_wallets enable row level security;
alter table public.hub_casino_log enable row level security;
revoke all on public.hub_wallets, public.hub_casino_log from anon, authenticated;
grant select on public.hub_wallets, public.hub_casino_log to authenticated;
create policy wallet_read on public.hub_wallets for select to authenticated using(public.hub_is_member() and (member_id=auth.uid() or public.hub_is_admin()));
create policy casino_log_read on public.hub_casino_log for select to authenticated using(public.hub_is_member() and (member_id=auth.uid() or public.hub_is_admin()));
create or replace function public.hub_wallet() returns bigint language plpgsql security definer set search_path='' as $$ declare b bigint; begin if not public.hub_is_member() then raise exception 'Members only'; end if; insert into public.hub_wallets(member_id) values(auth.uid()) on conflict do nothing; select balance into b from public.hub_wallets where member_id=auth.uid(); return b; end $$;
create or replace function public.hub_spin(stake bigint) returns jsonb language plpgsql security definer set search_path='' as $$ declare b bigint; r integer[]:=array[]::integer[]; n integer; i integer; p bigint:=0; begin if not public.hub_is_member() then raise exception 'Members only'; end if; if stake is null or stake<1 or stake>1000000 then raise exception 'Invalid bet'; end if; perform public.hub_wallet(); select balance into b from public.hub_wallets where member_id=auth.uid() for update; if b<stake then raise exception 'Insufficient balance'; end if; for i in 1..3 loop n:=floor(random()*100); r:=array_append(r,case when n<30 then 0 when n<55 then 1 when n<75 then 2 when n<88 then 3 when n<97 then 4 else 5 end); end loop; if r[1]=r[2] and r[2]=r[3] then p:=stake*(array[4,6,10,20,50,500])[r[1]+1]; elsif r[1]=r[2] or r[1]=r[3] or r[2]=r[3] then p:=stake; end if; b:=b-stake+p; update public.hub_wallets set balance=b where member_id=auth.uid(); insert into public.hub_casino_log(member_id,actor,kind,bet,payout,reels,balance) values(auth.uid(),auth.uid(),'spin',stake,p,r,b); return jsonb_build_object('balance',b,'reels',r,'payout',p); end $$;
create or replace function public.hub_reset_wallet(target uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.hub_is_admin() then raise exception 'Admin only'; end if; if not exists(select 1 from public.hub_members where id=target) and not exists(select 1 from public.hub_admins where id=target) then raise exception 'Unknown member'; end if; insert into public.hub_wallets(member_id,balance) values(target,500000) on conflict(member_id) do update set balance=500000; insert into public.hub_casino_log(member_id,actor,kind,balance) values(target,auth.uid(),'reset',500000); end $$;
revoke execute on function public.hub_wallet(),public.hub_spin(bigint),public.hub_reset_wallet(uuid) from public,anon;
grant execute on function public.hub_wallet(),public.hub_spin(bigint),public.hub_reset_wallet(uuid) to authenticated;
